def verify(witness):
    """Fail-closed: raises on any failed check; returns True only if all pass."""
    # Check 0: witness is a dict with exactly the expected top-level shape.
    if not isinstance(witness, dict):
        raise AssertionError('witness must be a dict')
    expected_top = {'contract_sha256', 'contract_canonical_statement',
                    'required_pins', 'present_keys'}
    if set(witness.keys()) != expected_top:
        raise AssertionError('top-level keys mismatch')
    # Check 1: SHA field is the exact frozen-contract digest prefix.
    if witness['contract_sha256'] != '8fab17a4372ba50c':
        raise AssertionError('contract SHA mismatch')
    # Check 2: canonical statement is the pinned nonempty text of the frozen contract.
    stmt = witness['contract_canonical_statement']
    if not isinstance(stmt, str) or len(stmt) == 0:
        raise AssertionError('canonical statement missing')
    for token in ['limsup', 'min_{i<n}', 'p_{n+i}+p_{n-i}', 'p_n']:
        if token not in stmt:
            raise AssertionError('canonical statement missing token: ' + token)
    # Check 3: no required pin appears in the contract text or any present key.
    def has_pin(obj, pin):
        if isinstance(obj, str):
            return pin in obj
        if isinstance(obj, dict):
            return any((pin in str(k)) or has_pin(v, pin) for k, v in obj.items())
        if isinstance(obj, (list, tuple)):
            return any(has_pin(x, pin) for x in obj)
        return pin in str(obj)
    for pin in witness['required_pins']:
        if has_pin(stmt, pin):
            raise AssertionError('pin present in canonical statement: ' + pin)
        for k in witness['present_keys']:
            if has_pin(k, pin):
                raise AssertionError('pin present in contract key: ' + k)
    # Check 4: present_keys is exactly the frozen contract's five top-level keys.
    if sorted(witness['present_keys']) != sorted(
            ['canonical_statement', 'close_branch_A', 'close_branch_B',
             'non_results', 'known_traps']):
        raise AssertionError('present_keys mismatch')
    # Check 5: required_pins: exactly three, distinct, nonempty, disjoint from keys.
    pins = witness['required_pins']
    if len(pins) != 3 or len(set(pins)) != 3 or not all(isinstance(p, str) and p for p in pins):
        raise AssertionError('required_pins malformed')
    if set(pins) & set(witness['present_keys']):
        raise AssertionError('pin collides with contract key')
    return True
